function countUnbeaten(root: TreeNode | null): number {
  const visit = (n: TreeNode | null, maxAbove: number): number => {
    if (!n) return 0;
    const m = Math.max(maxAbove, n.val);
    return (n.val >= maxAbove ? 1 : 0) + visit(n.left, m) + visit(n.right, m);
  };
  return root ? visit(root, root.val) : 0;
}

