function countUnbeaten(root: TreeNode | null): number {
  if (!root) return 0;
  let count = 0;
  const stack: [TreeNode, number][] = [[root, root.val]];
  while (stack.length) {
    const [n, maxAbove] = stack.pop()!;
    if (n.val >= maxAbove) count++;
    const m = Math.max(maxAbove, n.val);
    if (n.left) stack.push([n.left, m]);
    if (n.right) stack.push([n.right, m]);
  }
  return count;
}

