class Solution:
    def countUnbeaten(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0
        count = 0
        stack = [(root, root.val)]
        while stack:
            n, max_above = stack.pop()
            if n.val >= max_above:
                count += 1
            m = max(max_above, n.val)
            for child in (n.left, n.right):
                if child:
                    stack.append((child, m))
        return count

